const data = $input.first().json;
const body = data.body || data;
// handles both Form Trigger (key 'Batch size') and Webhook POST JSON (key 'batch_size')
const bs = body['batch_size'] ?? body['Batch size'] ?? 50;
return [{ json: { batch_size: Number(bs), run_id: 'qual-' + Date.now() } }];

function findLastValidJson(text) {
  if (!text) return null;
  const blocks = []; let depth = 0, start = -1;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') { if (depth === 0) start = i; depth++; }
    else if (text[i] === '}') { depth--; if (depth === 0 && start >= 0) { blocks.push([start, i + 1]); start = -1; } }
  }
  for (let i = blocks.length - 1; i >= 0; i--) {
    try {
      const obj = JSON.parse(text.substring(blocks[i][0], blocks[i][1]));
      if (obj && typeof obj === 'object' && 'is_icp' in obj) return obj;
    } catch (e) {}
  }
  for (let i = blocks.length - 1; i >= 0; i--) {
    try { return JSON.parse(text.substring(blocks[i][0], blocks[i][1])); } catch (e) {}
  }
  return null;
}
function clamp(n, min, max) { const x = typeof n === 'number' ? n : 0; return Math.max(min, Math.min(max, x)); }
function sizePtsFromCount(emp) {
  if (!emp || emp < 1) return 0;
  if (emp <= 10) return 0;
  if (emp <= 50) return 15;
  if (emp <= 200) return 20;
  if (emp <= 500) return 5;
  return 0;
}

const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const item = all[i];
  const t = item.json?.content?.[0]?.text || '';
  const v = findLastValidJson(t) || {};
  const orig = $('2b. Split companies → items').itemMatching(i)?.json || {};
  const empCount = Number(orig.numberofemployees || 0);

  const bk = v.score_breakdown || {};
  const industry_pts = clamp(bk.industry_pts, 0, 40);
  const country_pts = clamp(bk.country_pts, 0, 25);
  const size_pts_haiku = clamp(bk.size_pts, 0, 20);
  const size_pts_computed = sizePtsFromCount(empCount);
  const size_pts = empCount > 0 ? size_pts_computed : size_pts_haiku;
  const signals_pts = clamp(bk.signals_pts, 0, 15);

  const disqNum = v.disqualif_number && /^[1-5]$/.test(String(v.disqualif_number).trim()) ? String(v.disqualif_number).trim() : null;
  const sum = industry_pts + country_pts + size_pts + signals_pts;
  const score = disqNum ? 0 : sum;
  const is_icp = !disqNum && score >= 50;

  // Doubt flag — extended V3.8 to catch more false positives:
  // (a) ANY disqualif #2 or #5 (no sum threshold, since Haiku can also undervalue industry on healthcare/govtech)
  // (b) Score 40-55 sans disqualif (close to threshold)
  // (c) Industry undervalued (0 or 10 pts) but HQ France/EU detected + size in 11-500 range
  //     → suspicious that valid SaaS B2B got tagged as 'consulting/IT services'
  const _doubt = (
    disqNum === '1' && sum >= 50 ||  // V3.9: B2C marketplace claims souvent fausses sur SaaS B2B pour brands B2C
    disqNum === '2' ||
    disqNum === '5' ||
    (!disqNum && score >= 40 && score <= 55) ||
    (industry_pts <= 10 && country_pts >= 10 && empCount >= 11 && empCount <= 500)
  );

  out.push({
    json: {
      ...orig,
      _verdict: {
        is_icp, score,
        score_breakdown: { industry_pts, country_pts, size_pts, signals_pts },
        reason: v.reason || '',
        has_gtm_engineer: v.has_gtm_engineer === true,
        disqualif_number: disqNum,
        _doubt,
        _audit: {
          haiku_score: typeof v.score === 'number' ? v.score : null,
          haiku_is_icp: v.is_icp === true,
          haiku_breakdown: bk,
          numberofemployees: empCount,
          size_corrected: empCount > 0 && size_pts_haiku !== size_pts_computed,
          breakdown_sum_no_disq: sum,
        },
      },
    },
  });
}
return out;

if ($itemIndex !== 0) return [];
const verdicts = $('5.95 Merge confident + reviewed').all();
const total = verdicts.length;
let qualified = 0, disqualified = 0, sonnetReviewed = 0;
const lines = verdicts.map(v => {
  const j = v.json;
  const ver = j._verdict || {};
  if (ver.is_icp) qualified++; else disqualified++;
  if (ver._reviewed_by === 'sonnet') sonnetReviewed++;
  const bk = ver.score_breakdown || {};
  const breakdownStr = (typeof bk.industry_pts === 'number')
    ? ' [I:' + (bk.industry_pts||0) + ' C:' + (bk.country_pts||0) + ' Sz:' + (bk.size_pts||0) + ' Sg:' + (bk.signals_pts||0) + ']'
    : '';
  const sonnetTag = ver._reviewed_by === 'sonnet' ? ' 🤖' : '';
  return '   - ' + (ver.is_icp ? '✅' : '❌') + ' *' + (j.name || '?') + '* (score ' + (ver.score || 0) + ')' + breakdownStr + sonnetTag + '\n      _' + (ver.reason || '').slice(0, 150) + '_';
}).join('\n');
const summary = qualified === 0
  ? '🛑 *Aucune company qualifiée — Flow 4 terminé.*\n_' + total + ' companies analysées, 0 ✅._'
  : '✅ *' + qualified + '/' + total + ' compan' + (qualified > 1 ? 'ies qualifiées' : 'y qualifiée') + '*\n_Lance Flow 2 (Persona Enricher) pour scrap les personas._';
const sonnetNote = sonnetReviewed > 0 ? '\n\n_🤖 ' + sonnetReviewed + ' verdict(s) re-jugés par Sonnet (cas borderlines)_' : '';
const text = '📊 *Flow 4 — Company Qualifier*\n' + total + ' compan' + (total > 1 ? 'ies analysées' : 'y analysée') + sonnetNote + '\n\n_Légende breakdown: I=Industry, C=Country, Sz=Size, Sg=Signals (sur 100). 🤖 = re-jugé Sonnet_\n\n' + lines + '\n\n' + summary;
return [{ json: { text } }];

const today = new Date().toISOString().split('T')[0];
const all = $input.all();
const inputs = [];
for (const item of all) {
  const j = item.json;
  const v = j._verdict || {};
  if (!j.hs_id) continue;
  const bk = v.score_breakdown || {};
  const breakdownStr = (typeof bk.industry_pts === 'number')
    ? 'Industry ' + (bk.industry_pts||0) + ' + Country ' + (bk.country_pts||0) + ' + Size ' + (bk.size_pts||0) + ' + Signals ' + (bk.signals_pts||0) + ' = ' + (v.score||0)
    : '';
  const sonnetTag = v._reviewed_by === 'sonnet' ? ' [🤖 SONNET REVIEW]' : '';
  const disqTag = v.disqualif_number ? ' [Disqualif #' + v.disqualif_number + ']' : '';
  const richReason = '*Score:* ' + (v.score || 0) + sonnetTag + disqTag
    + (breakdownStr ? '\n*Breakdown:* ' + breakdownStr : '')
    + (v.reason ? '\n\n*Verdict:* ' + v.reason : '')
    + '\n\n*Company scoring date:* ' + today;
  inputs.push({
    id: j.hs_id,
    properties: {
      tam_status: v.is_icp ? 'qualified' : 'disqualified',
      score_icp: v.score || 0,
      qualified_reason: v.is_icp ? richReason : '',
      disqualif_reason: v.is_icp ? '' : richReason,
    },
  });
}
const CHUNK = 100;
const out = [];
for (let i = 0; i < inputs.length; i += CHUNK) {
  out.push({ json: { body: { inputs: inputs.slice(i, i + CHUNK) } } });
}
return out;

